    ON small_business_stores(legal_dong_code);

-- 한국부동산원 소규모 상가 임대료 (CSV 업로드)
CREATE TABLE reb_small_retail_rent_areas (
    reb_small_retail_rent_area_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_area_key VARCHAR(64) NOT NULL,
    source_row_number INTEGER NOT NULL,
    area_name VARCHAR(100) NOT NULL,
    area_path VARCHAR(500) NOT NULL,
    area_level SMALLINT NOT NULL,
    region_id BIGINT REFERENCES regions(region_id),
    commercial_area_id BIGINT REFERENCES commercial_areas(commercial_area_id),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_reb_small_retail_rent_areas_source_key UNIQUE (source_area_key),
    CONSTRAINT ck_reb_small_retail_rent_areas_single_mapping CHECK (
        region_id IS NULL OR commercial_area_id IS NULL
    )
);

CREATE TABLE reb_small_retail_rent_metrics (
    reb_small_retail_rent_metric_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    reb_small_retail_rent_area_id BIGINT NOT NULL
        REFERENCES reb_small_retail_rent_areas(reb_small_retail_rent_area_id),
    reference_year SMALLINT NOT NULL,
    reference_quarter SMALLINT NOT NULL,
    rent_per_square_meter_thousand_krw DECIMAL(12, 3) NOT NULL,
    source_file_name VARCHAR(255) NOT NULL,
    source_file_hash VARCHAR(64) NOT NULL,
    collected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT ck_reb_small_retail_rent_metrics_quarter CHECK (reference_quarter BETWEEN 1 AND 4),
    CONSTRAINT ck_reb_small_retail_rent_metrics_rent CHECK (
        rent_per_square_meter_thousand_krw >= 0
    ),
    CONSTRAINT uq_reb_small_retail_rent_metrics_area_period UNIQUE (
        reb_small_retail_rent_area_id, reference_year, reference_quarter
    )
);

CREATE INDEX idx_reb_small_retail_rent_areas_region
    ON reb_small_retail_rent_areas(region_id);

CREATE INDEX idx_reb_small_retail_rent_areas_commercial_area
    ON reb_small_retail_rent_areas(commercial_area_id);

CREATE INDEX idx_reb_small_retail_rent_metrics_period
    ON reb_small_retail_rent_metrics(reference_year, reference_quarter);

-- KOSIS 기업생멸행정통계 — 생존율 (DT_2BD1003)
CREATE TABLE kosis_business_survival_rates (
    kosis_business_survival_rate_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    organization_id VARCHAR(20) NOT NULL,
    table_id VARCHAR(50) NOT NULL,
    table_name VARCHAR(200),
    industry_code VARCHAR(50) NOT NULL,
    industry_name VARCHAR(200) NOT NULL,
    classification_name VARCHAR(200),
    item_id VARCHAR(50) NOT NULL,
    item_name VARCHAR(100) NOT NULL,
    unit_name VARCHAR(30) NOT NULL,
    period_type VARCHAR(10) NOT NULL,
    reference_year INT NOT NULL,
    survival_rate DECIMAL(7,3) NOT NULL,
    source_updated_at VARCHAR(30),
    collected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_kosis_business_survival_rate
        UNIQUE (table_id, industry_code, item_id, reference_year),
    CONSTRAINT chk_kosis_business_survival_reference_year
        CHECK (reference_year BETWEEN 1900 AND 2200),
    CONSTRAINT chk_kosis_business_survival_rate
        CHECK (survival_rate BETWEEN 0 AND 100)
);

CREATE INDEX idx_kosis_business_survival_year_industry
    ON kosis_business_survival_rates(reference_year, industry_code);

-- KOSIS 기업생멸행정통계 — 활동/신생/소멸 기업 수 (DT_1BD1001)
CREATE TABLE kosis_business_counts (
    kosis_business_count_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    organization_id VARCHAR(20) NOT NULL,
    table_id VARCHAR(50) NOT NULL,
    table_name VARCHAR(200),
    industry_code VARCHAR(50) NOT NULL,
    industry_name VARCHAR(200) NOT NULL,
    classification_name VARCHAR(200),
    item_id VARCHAR(50) NOT NULL,
    item_name VARCHAR(100) NOT NULL,
    unit_name VARCHAR(30) NOT NULL,
    period_type VARCHAR(10) NOT NULL,
    reference_year INT NOT NULL,
    business_count DECIMAL(20, 3) NOT NULL,
    source_updated_at VARCHAR(30),
    collected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_kosis_business_count
        UNIQUE (table_id, industry_code, item_id, reference_year),
    CONSTRAINT chk_kosis_business_count_reference_year
        CHECK (reference_year BETWEEN 1900 AND 2200),
    CONSTRAINT chk_kosis_business_count_non_negative
        CHECK (business_count >= 0)
);

CREATE INDEX idx_kosis_business_count_year_industry
    ON kosis_business_counts(reference_year, industry_code);

-- 활동(T01) 대비 신생(T02) · 소멸(T03) 비율
CREATE VIEW kosis_business_rates AS
SELECT
    organization_id,
    table_id,
    industry_code,
    MAX(industry_name) AS industry_name,
    reference_year,
    MAX(business_count) FILTER (WHERE item_id = 'T01') AS active_business_count,
    MAX(business_count) FILTER (WHERE item_id = 'T02') AS new_business_count,
    MAX(business_count) FILTER (WHERE item_id = 'T03') AS closed_business_count,
    ROUND(
        MAX(business_count) FILTER (WHERE item_id = 'T02')
            / NULLIF(MAX(business_count) FILTER (WHERE item_id = 'T01'), 0)
            * 100,
        3
    ) AS new_business_rate,
    ROUND(
        MAX(business_count) FILTER (WHERE item_id = 'T03')
            / NULLIF(MAX(business_count) FILTER (WHERE item_id = 'T01'), 0)
            * 100,
        3
    ) AS closure_rate
FROM kosis_business_counts
WHERE item_id IN ('T01', 'T02', 'T03')
GROUP BY organization_id, table_id, industry_code, reference_year;

-- 서울시 S-DoT 유동인구 센서 (IotVdata018)
CREATE TABLE seoul_sdot_foot_traffic (
    seoul_sdot_foot_traffic_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    model_name VARCHAR(50),
    serial_number VARCHAR(100) NOT NULL,
    sensing_time TIMESTAMP NOT NULL,
    region_type VARCHAR(100),
    autonomous_district VARCHAR(100),
    administrative_district VARCHAR(100),
    visitor_count BIGINT NOT NULL,
    registered_at TIMESTAMP,
    collected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_seoul_sdot_foot_traffic_sensor_time
        UNIQUE (serial_number, sensing_time),
    CONSTRAINT chk_seoul_sdot_foot_traffic_visitor_count
        CHECK (visitor_count >= 0)
);

CREATE INDEX idx_seoul_sdot_foot_traffic_sensing_time
    ON seoul_sdot_foot_traffic(sensing_time);

CREATE INDEX idx_seoul_sdot_foot_traffic_district
    ON seoul_sdot_foot_traffic(autonomous_district, administrative_district);

CREATE VIEW seoul_sdot_latest_sensor_traffic AS
SELECT DISTINCT ON (serial_number)
    serial_number,
    model_name,
    sensing_time,
    region_type,
    autonomous_district,
    administrative_district,
    visitor_count,
    registered_at
FROM seoul_sdot_foot_traffic
ORDER BY serial_number, sensing_time DESC;

CREATE VIEW seoul_sdot_district_traffic_metrics AS
SELECT
    autonomous_district,
    administrative_district,
    COUNT(*) AS sensor_count,
    SUM(visitor_count) AS total_visitor_count,
    ROUND(AVG(visitor_count), 3) AS average_visitor_count,
    MIN(sensing_time) AS oldest_sensing_time,
    MAX(sensing_time) AS latest_sensing_time
FROM seoul_sdot_latest_sensor_traffic
WHERE autonomous_district IS NOT NULL
  AND autonomous_district <> ''
  AND administrative_district IS NOT NULL
  AND administrative_district <> ''
GROUP BY autonomous_district, administrative_district;

-- 서울시 실시간 도시데이터 인구 (citydata_ppltn)
CREATE TABLE seoul_realtime_city_populations (
    seoul_realtime_city_population_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    area_code VARCHAR(30) NOT NULL,
    area_name VARCHAR(150) NOT NULL,
    congestion_level VARCHAR(30),
    congestion_message VARCHAR(1000),
    population_min BIGINT NOT NULL,
    population_max BIGINT NOT NULL,
    estimated_population BIGINT NOT NULL,
    male_population_rate DECIMAL(6, 3),
    female_population_rate DECIMAL(6, 3),
    population_rate_0 DECIMAL(6, 3),
    population_rate_10 DECIMAL(6, 3),
    population_rate_20 DECIMAL(6, 3),
    population_rate_30 DECIMAL(6, 3),
    population_rate_40 DECIMAL(6, 3),
    population_rate_50 DECIMAL(6, 3),
    population_rate_60 DECIMAL(6, 3),
    population_rate_70 DECIMAL(6, 3),
    resident_population_rate DECIMAL(6, 3),
    non_resident_population_rate DECIMAL(6, 3),
    replacement_used BOOLEAN NOT NULL DEFAULT false,
    population_time TIMESTAMP NOT NULL,
    collected_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_seoul_realtime_city_population_area_time
        UNIQUE (area_code, population_time),
    CONSTRAINT chk_seoul_realtime_city_population_range
        CHECK (population_min >= 0 AND population_max >= population_min),
    CONSTRAINT chk_seoul_realtime_city_population_estimate
        CHECK (estimated_population BETWEEN population_min AND population_max)
);

CREATE INDEX idx_seoul_realtime_city_population_area_latest
    ON seoul_realtime_city_populations(area_code, population_time DESC);

CREATE VIEW seoul_realtime_city_latest_populations AS
SELECT DISTINCT ON (area_code)
    area_code,
    area_name,
    congestion_level,
    population_min,
    population_max,
    estimated_population,
    male_population_rate,
    female_population_rate,
    population_rate_0,
    population_rate_10,
    population_rate_20,
    population_rate_30,
    population_rate_40,
    population_rate_50,
    population_rate_60,
    population_rate_70,
    resident_population_rate,
    non_resident_population_rate,
    replacement_used,
    population_time
FROM seoul_realtime_city_populations
ORDER BY area_code, population_time DESC;


-- =========================================================================
-- 8. 분석 수집 실행
-- =========================================================================
CREATE TABLE analysis_collection_runs (
    analysis_collection_run_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id BIGINT NOT NULL REFERENCES users(user_id),
    analysis_type VARCHAR(20) NOT NULL,
    region_code VARCHAR(30) NOT NULL,
    industry_code VARCHAR(50) NOT NULL,
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT chk_analysis_collection_run_type
        CHECK (analysis_type IN ('PROFIT', 'SURVIVAL')),
    CONSTRAINT chk_analysis_collection_run_status
        CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED'))
);

CREATE TABLE analysis_collection_tasks (
    analysis_collection_task_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    analysis_collection_run_id BIGINT NOT NULL
        REFERENCES analysis_collection_runs(analysis_collection_run_id) ON DELETE CASCADE,
    data_type VARCHAR(100) NOT NULL,
    target_key VARCHAR(100) NOT NULL,
    status VARCHAR(20) NOT NULL,
    attempt_count INTEGER NOT NULL DEFAULT 0,
    error_message VARCHAR(2000),
    started_at TIMESTAMPTZ,
    finished_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ,
    CONSTRAINT uq_analysis_collection_task
        UNIQUE (analysis_collection_run_id, data_type, target_key),
    CONSTRAINT chk_analysis_collection_task_status
        CHECK (status IN ('PENDING', 'RUNNING', 'COMPLETED', 'FAILED')),
    CONSTRAINT chk_analysis_collection_task_attempt_count
        CHECK (attempt_count >= 0)
);

CREATE INDEX idx_analysis_collection_runs_user_created
    ON analysis_collection_runs(user_id, created_at DESC);

CREATE INDEX idx_analysis_collection_tasks_run_status
    ON analysis_collection_tasks(analysis_collection_run_id, status);


