INSERT INTO region_external_code_mappings (
    region_code,
    source,
    external_code,
    external_name
)
SELECT
    source_data.region_code,
    'SMALL_BUSINESS_STORE',
    source_data.external_code,
    source_data.external_name
FROM source_data
WHERE source_data.evidence_store_count > 0
ON CONFLICT ON CONSTRAINT uq_region_external_code_mapping
DO UPDATE SET external_name = EXCLUDED.external_name;

