    ('3130320', '암사종합시장', 'TRADITIONAL_MARKET'),
    ('3130321', '장신구 특화거리 상점가', 'TRADITIONAL_MARKET'),
    ('3130322', '고분다리전통시장', 'TRADITIONAL_MARKET'),
    ('3130323', '둔촌역전통시장', 'TRADITIONAL_MARKET'),
    ('3130324', '길동복조리시장', 'TRADITIONAL_MARKET'),
    ('3130325', '명일전통시장', 'TRADITIONAL_MARKET'),
    ('3130326', '고덕 골목형상점가', 'TRADITIONAL_MARKET'),
    ('3130327', '평화시장(남평화시장, 제일평화시장, 신평화패션타운)', 'TRADITIONAL_MARKET');
DO $$
DECLARE
    source_record RECORD;
    resolved_commercial_area_id BIGINT;
BEGIN
    FOR source_record IN
        SELECT external_code, name, type
        FROM seed_seoul_commercial_areas
        ORDER BY external_code
    LOOP
        SELECT mapping.commercial_area_id
        INTO resolved_commercial_area_id
        FROM commercial_area_external_code_mappings mapping
        WHERE mapping.source = 'SEOUL_ESTIMATED_SALES'
          AND mapping.external_code = source_record.external_code
        ORDER BY mapping.commercial_area_id
        LIMIT 1;

        IF resolved_commercial_area_id IS NULL THEN
            INSERT INTO commercial_areas (name, type, status)
            VALUES (source_record.name, source_record.type, 'ACTIVE')
            RETURNING commercial_area_id INTO resolved_commercial_area_id;

            INSERT INTO commercial_area_external_code_mappings (
                commercial_area_id,
                source,
                external_code,
                external_name
            )
            VALUES (
                resolved_commercial_area_id,
                'SEOUL_ESTIMATED_SALES',
                source_record.external_code,
                source_record.name
            );
        ELSE
            UPDATE commercial_area_external_code_mappings
            SET external_name = source_record.name
            WHERE commercial_area_id = resolved_commercial_area_id
              AND source = 'SEOUL_ESTIMATED_SALES'
              AND external_code = source_record.external_code;
        END IF;
    END LOOP;
END
$$;

INSERT INTO commercial_area_region_mappings (
    commercial_area_id,
    region_id,
    is_primary
)
SELECT DISTINCT
    commercial_area_mapping.commercial_area_id,
    region.region_id,
    false
FROM region_external_code_mappings region_mapping
JOIN regions region
  ON region.code = region_mapping.region_code
JOIN commercial_area_external_code_mappings commercial_area_mapping
  ON commercial_area_mapping.source = 'SEOUL_ESTIMATED_SALES'
 AND commercial_area_mapping.external_code = region_mapping.external_code
WHERE region_mapping.source = 'SEOUL_ESTIMATED_SALES'
ON CONFLICT ON CONSTRAINT uq_commercial_area_region
DO NOTHING;